"use client";

import "./idea-project.css";
import "./tag-library.css";
import "./idea-edit.css";
import "./project-overview.css";
import "./profile.css";
import "./records.css";
import "./enhancements.css";
import { useEffect, useState, type KeyboardEvent } from "react";
import { Archive, ArrowLeft, ArrowRight, ArrowUp, BookOpen, Check, ChevronLeft, ChevronRight, Clock3, Compass, Eye, EyeOff, KeyRound, Lightbulb, Menu, Pencil, Play, Plus, Search, Square, Timer, Trash2, UserRound, X } from "lucide-react";
import { createActivityRecord, createIdea, createProject, createProjectMessage, createTag, getActiveTimer, getActivityRecords, getIdeas, getLlmConfig, getProjectMessages, getProjects, getTags, saveActiveTimer, saveActivityRecords, saveIdeas, saveLlmConfig, saveProjectMessages, saveProjects, saveTags, type ActiveTimer, type ActivityRecord, type Idea, type LlmConfig, type Project, type ProjectMessage, type Tag } from "@/lib/storage";

type View = "explore" | "ideas" | "projects" | "records" | "profile";
type IdeasTab = "ideas" | "tags";
type ProfileTab = "overview" | "model" | "archive";
type RecordsPeriod = "day" | "week" | "month" | "year";
type ChatMessage = { role: "user" | "assistant"; content: string };
const nav: [View, string, typeof Compass][] = [["explore", "探索", Compass], ["ideas", "想法", Lightbulb], ["projects", "项目", BookOpen], ["records", "记录", Timer], ["profile", "我的", UserRound]];
const providerPresets: Record<LlmConfig["provider"], Pick<LlmConfig, "baseUrl" | "model">> = {
  deepseek: { baseUrl: "https://api.deepseek.com/chat/completions", model: "deepseek-chat" },
  openai: { baseUrl: "https://api.openai.com/v1/chat/completions", model: "gpt-4.1-mini" },
  qwen: { baseUrl: "https://dashscope.aliyuncs.com/compatible-mode/v1/chat/completions", model: "qwen-plus" },
  kimi: { baseUrl: "https://api.moonshot.cn/v1/chat/completions", model: "moonshot-v1-8k" },
  custom: { baseUrl: "", model: "" },
};

async function askLlm(config: LlmConfig, system: string, messages: ChatMessage[]) {
  if (!config.apiKey.trim()) throw new Error("missing-key");
  if (!config.baseUrl.trim() || !config.model.trim()) throw new Error("missing-model");
  const response = await fetch(config.baseUrl.trim(), { method: "POST", headers: { "Content-Type": "application/json", Authorization: `Bearer ${config.apiKey.trim()}` }, body: JSON.stringify({ model: config.model.trim(), messages: [{ role: "system", content: system }, ...messages], temperature: 0.7 }) });
  const data = await response.json() as { choices?: { message?: { content?: string } }[]; error?: { message?: string } | string };
  const answer = data.choices?.[0]?.message?.content?.trim();
  if (!response.ok || !answer) throw new Error(typeof data.error === "string" ? data.error : data.error?.message ?? "empty-response");
  return answer;
}

function dateLabel(value: string) { return new Intl.DateTimeFormat("zh-CN", { year: "numeric", month: "long", day: "numeric" }).format(new Date(value)); }
function ideaTitle(content: string) { const normalized = content.replace(/\s+/g, " ").trim(); return normalized.length > 48 ? `${normalized.slice(0, 48)}…` : normalized; }
function tagPath(tag: Tag, tags: Tag[]) { const parent = tags.find((item) => item.id === tag.parentId); return parent ? `${parent.name} / ${tag.name}` : tag.name; }

export default function Home() {
  const [view, setView] = useState<View>("explore"); const [ideas, setIdeas] = useState<Idea[]>([]); const [tags, setTags] = useState<Tag[]>([]); const [projects, setProjects] = useState<Project[]>([]); const [activityRecords, setActivityRecords] = useState<ActivityRecord[]>([]); const [projectMessages, setProjectMessages] = useState<ProjectMessage[]>([]); const [llmConfig, setLlmConfig] = useState<LlmConfig>(() => ({ ...providerPresets.deepseek, provider: "deepseek", apiKey: "" })); const [activeTimer, setActiveTimer] = useState<ActiveTimer | null>(null); const [loaded, setLoaded] = useState(false); const [menu, setMenu] = useState(false); const [selectedIdeaId, setSelectedIdeaId] = useState<string | null>(null); const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);
  useEffect(() => { const frame = requestAnimationFrame(() => { const storedIdeas = getIdeas(); setTags(getTags()); setIdeas(storedIdeas); setProjects(getProjects()); setActivityRecords(getActivityRecords()); setProjectMessages(getProjectMessages()); setLlmConfig(getLlmConfig()); setActiveTimer(getActiveTimer()); setLoaded(true); }); return () => cancelAnimationFrame(frame); }, []);
  useEffect(() => { if (loaded) saveIdeas(ideas); }, [ideas, loaded]); useEffect(() => { if (loaded) saveTags(tags); }, [tags, loaded]); useEffect(() => { if (loaded) saveProjects(projects); }, [projects, loaded]); useEffect(() => { if (loaded) saveActivityRecords(activityRecords); }, [activityRecords, loaded]); useEffect(() => { if (loaded) saveProjectMessages(projectMessages); }, [projectMessages, loaded]); useEffect(() => { if (loaded) saveLlmConfig(llmConfig); }, [llmConfig, loaded]); useEffect(() => { if (loaded) saveActiveTimer(activeTimer); }, [activeTimer, loaded]);
  const go = (next: View) => { setView(next); setMenu(false); };
  const addIdea = (input: Omit<Idea, "id" | "createdAt" | "updatedAt">) => { const idea = createIdea(input); setIdeas((current) => [idea, ...current]); setSelectedIdeaId(null); go("ideas"); };
  const updateIdea = (next: Idea) => {
    const updatedAt = new Date().toISOString();
    setIdeas((current) => current.map((idea) => idea.id === next.id ? { ...next, updatedAt } : idea));
    if (next.status === "archived") setProjects((current) => current.map((project) => project.linkedIdeaId === next.id && project.status !== "archived" ? { ...project, status: "archived", updatedAt } : project));
  };
  const updateProject = (next: Project) => setProjects((current) => current.map((project) => project.id === next.id ? { ...next, updatedAt: new Date().toISOString() } : project));
  const removeIdea = (id: string) => { setIdeas((current) => current.filter((idea) => idea.id !== id)); setSelectedIdeaId(null); };
  const openProject = (id: string) => { setSelectedProjectId(id); go("projects"); };
  const createFromIdea = (idea: Idea) => { const existing = projects.find((project) => project.linkedIdeaId === idea.id); if (existing) { updateIdea({ ...idea, status: "convertedToProject" }); openProject(existing.id); return; } const project = createProject({ title: idea.title, description: idea.content, status: "active", linkedIdeaId: idea.id }); setProjects((current) => [project, ...current]); updateIdea({ ...idea, status: "convertedToProject" }); setSelectedProjectId(project.id); go("projects"); };
  const continueProject = () => { const project = projects.find((item) => item.status === "active" || item.status === "paused"); if (project) openProject(project.id); };
  const addRecord = (record: Omit<ActivityRecord, "id">) => setActivityRecords((current) => [createActivityRecord(record), ...current]);
  return <main className="app"><aside className={menu ? "side open" : "side"}><div className="brand"><Mark />Ariadne</div><p className="motto">Find your way<br />through the maze.</p><nav>{nav.map(([itemView, label, Icon]) => <button key={itemView} className={view === itemView ? "active" : ""} onClick={() => go(itemView)}><Icon size={18} />{label}{itemView === "ideas" && <b>{ideas.filter((idea) => idea.status !== "archived").length}</b>}</button>)}</nav><small>○ ┄ ○ ┄ <i>●</i> ┄ ○<br /><br />你正在留下自己的线。</small></aside><header className="mobile"><button aria-label="打开导航" onClick={() => setMenu(true)}><Menu /></button><div className="brand"><Mark />Ariadne</div><button aria-label="查看想法" onClick={() => go("ideas")}><Plus /></button></header><section className="content">{view === "explore" && <Explore llmConfig={llmConfig} onOpenModelSettings={() => go("profile")} onCreateIdea={addIdea} onContinue={continueProject} hasProject={projects.some((item) => item.status === "active" || item.status === "paused")} />}{view === "ideas" && <Ideas ideas={ideas} tags={tags} projects={projects} selectedIdeaId={selectedIdeaId} onSelectIdea={setSelectedIdeaId} onCreateIdea={addIdea} onUpdateIdea={updateIdea} onDeleteIdea={removeIdea} onUpdateTags={setTags} onOpenProject={openProject} onCreateProject={createFromIdea} />}{view === "projects" && <Projects projects={projects} ideas={ideas} messages={projectMessages} llmConfig={llmConfig} activeTimer={activeTimer} selectedProjectId={selectedProjectId} onSelect={setSelectedProjectId} onUpdate={updateProject} onSetTimer={setActiveTimer} onAddRecord={addRecord} onAddMessage={(message) => setProjectMessages((current) => [...current, createProjectMessage(message)])} onOpenIdea={(id) => { setSelectedIdeaId(id); go("ideas"); }} onOpenModelSettings={() => go("profile")} />}{view === "records" && <Records records={activityRecords} tags={tags} projects={projects} onAdd={addRecord} />}{view === "profile" && <Profile ideas={ideas} projects={projects} tags={tags} records={activityRecords} llmConfig={llmConfig} onUpdateLlmConfig={setLlmConfig} onRestoreIdea={(idea) => { updateIdea({ ...idea, status: "inbox" }); setSelectedIdeaId(idea.id); go("ideas"); }} onRestoreProject={(project) => { updateProject({ ...project, status: "active" }); setSelectedProjectId(project.id); go("projects"); }} />}</section><nav className="bottom">{nav.map(([itemView, label, Icon]) => <button key={itemView} className={view === itemView ? "active" : ""} onClick={() => go(itemView)}><Icon size={19} /><span>{label}</span></button>)}</nav></main>;
}
function Mark() { return <span className="mark"><i /><i /><i /></span>; }

function Explore({ llmConfig, onOpenModelSettings, onCreateIdea, onContinue, hasProject }: { llmConfig: LlmConfig; onOpenModelSettings: () => void; onCreateIdea: (input: Omit<Idea, "id" | "createdAt" | "updatedAt">) => void; onContinue: () => void; hasProject: boolean }) {
  const [messages, setMessages] = useState<ChatMessage[]>([{ role: "assistant", content: "你不需要现在就知道自己想做什么。告诉我最近在意、好奇或放不下的事，我们一起把它慢慢说清楚。" }]);
  const [chatInput, setChatInput] = useState(""); const [replying, setReplying] = useState(false); const [error, setError] = useState("");
  const saveIdea = (content: string) => onCreateIdea({ title: ideaTitle(content), content: content.trim(), tagIds: [], status: "inbox" });
  const send = async (preset?: string) => {
    const content = (preset ?? chatInput).trim(); if (!content || replying) return;
    if (!llmConfig.apiKey.trim()) { setError("先在「我的 → 模型」中接入你的 API Key，就可以开始对话。"); return; }
    const nextMessages = [...messages, { role: "user" as const, content }]; setMessages(nextMessages); setChatInput(""); setError(""); setReplying(true);
    try { const answer = await askLlm(llmConfig, "你是 Ariadne 的想法引导伙伴。通过自然对话帮助用户发现值得尝试的方向。语气温和、具体、不评判；每次只追问一个最有帮助的问题。信息足够时，给出 1—3 个轻量、可在今天开始的想法，不要替用户做长期计划。用简洁中文回复，控制在 180 字内。", nextMessages); setMessages((current) => [...current, { role: "assistant", content: answer }]); }
    catch (requestError) { setError(requestError instanceof Error && requestError.message === "missing-key" ? "还没有配置 API Key。" : "这次没有连上模型，请检查 API Key、接口地址、模型名称和账户额度。"); }
    finally { setReplying(false); }
  };
  return <div className="explore explore-chat llm-explore"><div className="explore-conversation">{messages.map((message, index) => <div className={`explore-message ${message.role}`} key={`${message.role}-${index}`}><div className="chat-avatar">{message.role === "assistant" ? "A" : "我"}</div><div><div className="eyebrow">{message.role === "assistant" ? "ARIADNE" : "YOU"}</div><p>{message.content}</p>{message.role === "assistant" && index > 0 && <button className="save-as-idea" onClick={() => saveIdea(message.content)}><Lightbulb size={14} />保存为想法</button>}</div></div>)}{replying && <div className="explore-message assistant thinking"><div className="chat-avatar">A</div><p>正在想一想…</p></div>}</div>{messages.length === 1 && <><p className="chat-question">此刻，哪一句更接近你？</p><div className="chat-options"><button onClick={() => send("我不知道自己想做什么，请陪我找一个可以开始的方向。")}>我不知道应该做什么 <ChevronRight size={17} /></button><button onClick={() => send("我有一个还很模糊的新想法，想和你一起把它说清楚。")}>我有一个模糊的想法 <ChevronRight size={17} /></button><button className={!hasProject ? "placeholder-choice" : ""} disabled={!hasProject} onClick={onContinue}>我想继续推进之前的事情 <ChevronRight size={17} /></button></div></>}<form className="chat-composer" onSubmit={(event) => { event.preventDefault(); send(); }}><input value={chatInput} onChange={(event) => setChatInput(event.target.value)} placeholder="告诉我你最近在想什么…" /><button type="submit" disabled={!chatInput.trim() || replying}><ArrowUp size={18} /></button></form>{error && <div className="llm-error"><span>{error}</span><button onClick={onOpenModelSettings}>去配置 <ArrowRight size={14} /></button></div>}<p className="chat-footnote">对话由你在“我的”中接入的模型生成；满意的回答可以保存为想法。</p></div>;
}

function Ideas({ ideas, tags, projects, selectedIdeaId, onSelectIdea, onCreateIdea, onUpdateIdea, onDeleteIdea, onUpdateTags, onOpenProject, onCreateProject }: { ideas: Idea[]; tags: Tag[]; projects: Project[]; selectedIdeaId: string | null; onSelectIdea: (id: string | null) => void; onCreateIdea: (input: Omit<Idea, "id" | "createdAt" | "updatedAt">) => void; onUpdateIdea: (idea: Idea) => void; onDeleteIdea: (id: string) => void; onUpdateTags: (tags: Tag[]) => void; onOpenProject: (id: string) => void; onCreateProject: (idea: Idea) => void }) {
  const [tab, setTab] = useState<IdeasTab>("ideas"); const [formOpen, setFormOpen] = useState(false); const [content, setContent] = useState(""); const [search, setSearch] = useState(""); const [filterTagId, setFilterTagId] = useState<string | null>(null); const selected = ideas.find((idea) => idea.id === selectedIdeaId) ?? null;
  const activeFilterIds = filterTagId ? [filterTagId, ...tags.filter((tag) => tag.parentId === filterTagId).map((tag) => tag.id)] : [];
  const visible = ideas.filter((idea) => idea.status !== "archived" && (!activeFilterIds.length || idea.tagIds.some((id) => activeFilterIds.includes(id))) && `${idea.title} ${idea.content}`.toLowerCase().includes(search.toLowerCase()));
  const save = () => { if (!content.trim()) return; onCreateIdea({ title: ideaTitle(content), content: content.trim(), tagIds: [], status: "inbox" }); setContent(""); setFormOpen(false); };
  if (selected) return <IdeaDetail key={selected.id} idea={selected} tags={tags} project={projects.find((project) => project.linkedIdeaId === selected.id)} onBack={() => onSelectIdea(null)} onSave={onUpdateIdea} onDelete={() => onDeleteIdea(selected.id)} onOpenProject={onOpenProject} onCreateProject={() => onCreateProject(selected)} />;
  return <div className="page"><header><div><div className="eyebrow">IDEA INBOX</div><h1>想法，不必立刻变成计划。</h1><p>把它们先放在这里，等准备好的时候再靠近一点。</p></div><button className="primary" onClick={() => setFormOpen(true)}><Plus size={16} />记下想法</button></header><div className="view-tabs"><button className={tab === "ideas" ? "active" : ""} onClick={() => setTab("ideas")}>全部想法</button><button className={tab === "tags" ? "active" : ""} onClick={() => setTab("tags")}>标签</button></div>{tab === "tags" ? <TagManager tags={tags} ideas={ideas} onUpdateTags={onUpdateTags} onUpdateIdeas={(next) => next.forEach(onUpdateIdea)} onFilter={(id) => { setFilterTagId(id); setTab("ideas"); }} /> : <><div className="searchbar"><Search size={16} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="搜索想法" />{filterTagId && <button onClick={() => setFilterTagId(null)}>清除标签筛选</button>}</div>{formOpen && <div className="idea-form"><textarea autoFocus value={content} onChange={(event) => setContent(event.target.value)} placeholder="脑子里刚刚闪过什么？" /><div><button className="primary" onClick={save}>保存</button><button className="icon-button" onClick={() => setFormOpen(false)}><X size={18} /></button></div></div>}<div className="idea-list">{visible.map((idea) => <button className="idea-row" key={idea.id} onClick={() => onSelectIdea(idea.id)}><i /><div><h2>{idea.title}</h2><p>{idea.tagIds.map((id) => tags.find((tag) => tag.id === id)).filter(Boolean).map((tag) => `#${tag!.name}`).join("　") || "未分类"}　{dateLabel(idea.createdAt)}</p></div>{idea.status === "convertedToProject" && <span>已开启项目</span>}</button>)}{!visible.length && <p className="empty-note">这里还没有符合条件的想法。</p>}</div></>}</div>;
}

function TagManager({ tags, ideas, onUpdateTags, onUpdateIdeas, onFilter }: { tags: Tag[]; ideas: Idea[]; onUpdateTags: (tags: Tag[]) => void; onUpdateIdeas: (ideas: Idea[]) => void; onFilter: (id: string) => void }) {
  const [name, setName] = useState(""); const [parentId, setParentId] = useState<string>(""); const [editing, setEditing] = useState<Tag | null>(null); const [message, setMessage] = useState(""); const parents = tags.filter((tag) => tag.parentId === null); const usageCount = (id: string) => { const included = [id, ...tags.filter((tag) => tag.parentId === id).map((tag) => tag.id)]; return ideas.filter((idea) => idea.tagIds.some((tagId) => included.includes(tagId))).length; };
  const create = () => { if (!name.trim()) return; onUpdateTags([...tags, createTag({ name: name.trim(), parentId: parentId || null, type: "custom" })]); setName(""); setParentId(""); };
  const deleteTag = (tag: Tag) => { if (tag.type === "system") return; if (tags.some((item) => item.parentId === tag.id)) { setMessage("该一级标签下仍有子标签，请先删除或移动子标签。"); return; } if (!window.confirm(`删除标签「${tag.name}」？想法不会被删除，只会解除关联。`)) return; onUpdateTags(tags.filter((item) => item.id !== tag.id)); onUpdateIdeas(ideas.filter((idea) => idea.tagIds.includes(tag.id)).map((idea) => ({ ...idea, tagIds: idea.tagIds.filter((id) => id !== tag.id) }))); setMessage(""); };
  const linkedIdeas = ideas.filter((idea) => idea.tagIds.length > 0).length;
  return <div className="tag-manager"><div className="tag-overview"><div><div className="eyebrow">TAG LIBRARY</div><h2>让每个想法有迹可循。</h2><p>点击标签，回到所有与它有关的想法。</p></div><div className="tag-metrics"><span><b>{parents.length}</b>个主题</span><span><b>{linkedIdeas}</b>条已标记想法</span></div></div>{message && <p className="form-message">{message}</p>}<div className="tag-tree">{parents.map((parent, parentIndex) => { const children = tags.filter((tag) => tag.parentId === parent.id); return <section className={`tag-group tag-hue-${parentIndex % 5}`} key={parent.id}><div className="tag-parent"><button onClick={() => onFilter(parent.id)}><i /><span><b>{parent.name}</b><small>{children.length ? `${children.length} 个子标签` : "一级标签"}</small></span><em>{usageCount(parent.id)} <small>想法</small></em></button>{parent.type === "custom" && <TagButtons onEdit={() => setEditing(parent)} onDelete={() => deleteTag(parent)} />}</div>{children.length > 0 && <div className="tag-children">{children.map((child) => <div className="tag-child" key={child.id}><button onClick={() => onFilter(child.id)}><i />{child.name}<small>{usageCount(child.id)}</small></button>{child.type === "custom" && <TagButtons onEdit={() => setEditing(child)} onDelete={() => deleteTag(child)} />}</div>)}</div>}</section>; })}</div><div className="tag-create"><div><div className="eyebrow">CUSTOM TAG</div><h2>新建标签</h2></div><input value={name} onChange={(event) => setName(event.target.value)} placeholder="名称，例如：摄影" /><select value={parentId} onChange={(event) => setParentId(event.target.value)}><option value="">无 / 一级标签</option>{parents.map((tag) => <option key={tag.id} value={tag.id}>{tag.name}</option>)}</select><button className="primary" onClick={create}>创建</button></div>{editing && <div className="dialog-backdrop"><div className="dialog"><h2>修改标签</h2><input autoFocus value={editing.name} onChange={(event) => setEditing({ ...editing, name: event.target.value })} /><div className="dialog-actions"><button onClick={() => setEditing(null)}>取消</button><button className="primary" onClick={() => { if (!editing.name.trim()) return; onUpdateTags(tags.map((tag) => tag.id === editing.id ? { ...editing, name: editing.name.trim(), updatedAt: new Date().toISOString() } : tag)); setEditing(null); }}>保存</button></div></div></div>}</div>;
}
function TagButtons({ onEdit, onDelete }: { onEdit: () => void; onDelete: () => void }) { return <span className="tag-actions"><button aria-label="修改标签" onClick={onEdit}><Pencil size={13} /></button><button aria-label="删除标签" onClick={onDelete}><Trash2 size={13} /></button></span>; }

function IdeaDetail({ idea, tags, project, onBack, onSave, onDelete, onOpenProject, onCreateProject }: { idea: Idea; tags: Tag[]; project?: Project; onBack: () => void; onSave: (idea: Idea) => void; onDelete: () => void; onOpenProject: (id: string) => void; onCreateProject: () => void }) {
  const [editing, setEditing] = useState(false); const [draft, setDraft] = useState(idea); const [confirming, setConfirming] = useState(false); const [pickerOpen, setPickerOpen] = useState(false);
  const toggleTag = (id: string) => setDraft((current) => ({ ...current, tagIds: current.tagIds.includes(id) ? current.tagIds.filter((item) => item !== id) : [...current.tagIds, id] })); const save = () => { if (!draft.title.trim()) return; onSave({ ...draft, title: draft.title.trim(), content: draft.content.trim() }); setEditing(false); };
  return <div className="page detail"><button className="back" onClick={onBack}><ArrowLeft size={16} />返回想法</button>{editing ? <><label className="idea-edit-field"><span>标题</span><input className="detail-title-input" value={draft.title} onChange={(event) => setDraft({ ...draft, title: event.target.value })} placeholder="为这个想法起个名字" /></label><label className="idea-edit-field"><span>详细介绍</span><textarea className="detail-content" value={draft.content} onChange={(event) => setDraft({ ...draft, content: event.target.value })} placeholder="写下它为什么值得被记住、你想从哪里开始…" /></label><TagPicker tags={tags} selectedIds={draft.tagIds} onToggle={toggleTag} open={pickerOpen} setOpen={setPickerOpen} /><div className="detail-actions"><button onClick={() => { setDraft(idea); setEditing(false); }}>取消</button><button className="primary" onClick={save}>保存想法</button></div></> : <><div className="eyebrow">{idea.status === "convertedToProject" ? "已开启项目" : "IDEA"}</div><h1>{idea.title}</h1><section className="idea-description"><h2>详细介绍</h2><p className="detail-content read-only">{idea.content || "还没有补充介绍。"}</p></section><section className="detail-section"><h2>标签</h2><TagPills ids={idea.tagIds} tags={tags} /><button className="text-button" onClick={() => setEditing(true)}><Pencil size={14} />编辑标题、详细介绍与标签</button></section>{idea.status === "convertedToProject" ? project ? <section className="converted"><b>✓ 已开启项目</b><p>这个想法仍会保留，作为项目开始的来处。</p><button className="primary" onClick={() => onOpenProject(project.id)}>查看项目 <ArrowRight size={15} /></button></section> : <section className="converted"><b>✓ 已开启项目</b><p>关联的项目记录暂时不可用。</p></section> : <section className="start-project"><h2>准备好开始推进它了吗？</h2><p>想法会继续留在这里；开启项目后，可以从项目页继续前进。</p><button className="primary" onClick={() => setConfirming(true)}>开启这个项目 <ArrowRight size={16} /></button></section>}<div className="detail-actions secondary"><button onClick={() => setEditing(true)}><Pencil size={14} />编辑想法</button><button onClick={() => onSave({ ...idea, status: "archived" })}><Archive size={14} />归档</button><button className="danger" onClick={() => { if (window.confirm("删除这个想法？此操作不可恢复。")) onDelete(); }}><Trash2 size={14} />删除</button></div></>}{confirming && <div className="dialog-backdrop"><div className="dialog"><div className="eyebrow">开启项目</div><h2>你准备开始推进这个想法了吗？</h2><p>「{idea.title}」会被创建为一个新的项目。原始想法仍然会被保留，你之后仍然可以回来查看。</p><div className="dialog-actions"><button onClick={() => setConfirming(false)}>取消</button><button className="primary" onClick={onCreateProject}>开启项目</button></div></div></div>}</div>;
}
function TagPills({ ids, tags }: { ids: string[]; tags: Tag[] }) { return <div className="tag-pills">{ids.map((id) => tags.find((tag) => tag.id === id)).filter(Boolean).map((tag) => <span key={tag!.id}>{tagPath(tag!, tags)}</span>)}{!ids.length && <small>还没有标签</small>}</div>; }
function TagPicker({ tags, selectedIds, onToggle, open, setOpen }: { tags: Tag[]; selectedIds: string[]; onToggle: (id: string) => void; open: boolean; setOpen: (value: boolean) => void }) { return <section className="detail-section"><h2>标签</h2><div className="tag-pills">{selectedIds.map((id) => tags.find((tag) => tag.id === id)).filter(Boolean).map((tag) => <button key={tag!.id} onClick={() => onToggle(tag!.id)}>{tagPath(tag!, tags)} ×</button>)}<button className="add-tag" onClick={() => setOpen(!open)}>+ 添加标签</button></div>{open && <div className="tag-picker">{tags.map((tag) => <button key={tag.id} className={selectedIds.includes(tag.id) ? "selected" : ""} onClick={() => onToggle(tag.id)}>{selectedIds.includes(tag.id) ? "✓ " : ""}{tagPath(tag, tags)}</button>)}</div>}</section>; }

function Projects({ projects, ideas, messages, llmConfig, activeTimer, selectedProjectId, onSelect, onUpdate, onSetTimer, onAddRecord, onAddMessage, onOpenIdea, onOpenModelSettings }: { projects: Project[]; ideas: Idea[]; messages: ProjectMessage[]; llmConfig: LlmConfig; activeTimer: ActiveTimer | null; selectedProjectId: string | null; onSelect: (id: string) => void; onUpdate: (project: Project) => void; onSetTimer: (timer: ActiveTimer | null) => void; onAddRecord: (record: Omit<ActivityRecord, "id">) => void; onAddMessage: (message: Omit<ProjectMessage, "id" | "createdAt">) => void; onOpenIdea: (id: string) => void; onOpenModelSettings: () => void }) {
  const visibleProjects = projects.filter((item) => item.status !== "archived");
  const project = visibleProjects.find((item) => item.id === selectedProjectId) ?? visibleProjects[0];
  const [editingField, setEditingField] = useState<"title" | "description" | "thoughts" | null>(null);
  const [fieldDraft, setFieldDraft] = useState("");
  const [messageDraft, setMessageDraft] = useState("");
  const [replying, setReplying] = useState(false); const [chatError, setChatError] = useState(""); const [clockNow, setClockNow] = useState(() => Date.now());
  useEffect(() => { if (!activeTimer) return; setClockNow(Date.now()); const interval = window.setInterval(() => setClockNow(Date.now()), 1000); return () => window.clearInterval(interval); }, [activeTimer]);
  if (!project) return <Placeholder title="项目" description="从一个想法开启项目后，它会出现在这里。归档的项目可以在「我的」里查看。" />;
  const idea = ideas.find((item) => item.id === project.linkedIdeaId);
  const beginEdit = (field: "title" | "description" | "thoughts") => { setFieldDraft(field === "title" ? project.title : field === "description" ? project.description : project.innerThoughts ?? ""); setEditingField(field); };
  const saveField = () => { if (!editingField) return; const value = fieldDraft.trim(); if (editingField === "title" && !value) { setEditingField(null); return; } onUpdate({ ...project, ...(editingField === "title" ? { title: value } : editingField === "description" ? { description: value } : { innerThoughts: value }) }); setEditingField(null); };
  const cancelField = () => setEditingField(null);
  const editorKeyDown = (event: KeyboardEvent<HTMLInputElement | HTMLTextAreaElement>) => { if (event.key === "Escape") { event.preventDefault(); cancelField(); } if (event.key === "Enter" && (event.currentTarget instanceof HTMLInputElement || event.ctrlKey || event.metaKey)) event.currentTarget.blur(); };
  const currentMessages = messages.filter((message) => message.projectId === project.id).sort((a, b) => +new Date(a.createdAt) - +new Date(b.createdAt));
  const saveMessage = async () => { const content = messageDraft.trim(); if (!content || replying) return; if (!llmConfig.apiKey.trim()) { setChatError("先在「我的 → 模型」中接入 API Key。"); return; } const chatHistory = currentMessages.map((message) => ({ role: message.role, content: message.content })); onAddMessage({ projectId: project.id, role: "user", content }); setMessageDraft(""); setChatError(""); setReplying(true); try { const answer = await askLlm(llmConfig, `你是 Ariadne 的项目推进伙伴。当前项目是「${project.title}」，说明：${project.description || "暂无"}。帮助用户回顾进展、澄清卡点并决定一个最小下一步；不空泛鼓励，不一次拆出长清单。用简洁中文回复，不超过 160 字。`, [...chatHistory, { role: "user", content }]); onAddMessage({ projectId: project.id, role: "assistant", content: answer }); } catch { setChatError("这次没有连上模型，请检查 API Key、接口地址、模型名称和账户额度。"); } finally { setReplying(false); } };
  const isTiming = activeTimer?.projectId === project.id; const elapsedSeconds = isTiming ? Math.max(0, Math.floor((clockNow - new Date(activeTimer.startedAt).getTime()) / 1000)) : 0; const elapsedLabel = `${String(Math.floor(elapsedSeconds / 3600)).padStart(2, "0")}:${String(Math.floor((elapsedSeconds % 3600) / 60)).padStart(2, "0")}:${String(elapsedSeconds % 60).padStart(2, "0")}`;
  const stopTimer = () => { if (!activeTimer || activeTimer.projectId !== project.id) return; const completedAt = new Date(); const seconds = Math.max(1, Math.round((completedAt.getTime() - new Date(activeTimer.startedAt).getTime()) / 1000)); onAddRecord({ title: project.title, minutes: seconds / 60, tagId: null, projectId: project.id, note: "项目推进计时", startedAt: activeTimer.startedAt, completedAt: completedAt.toISOString() }); onSetTimer(null); };
  return <div className="project"><aside><div className="listtitle">项目 <b>{visibleProjects.length}</b></div>{visibleProjects.map((item) => <button className={item.id === project.id ? "selected" : ""} onClick={() => { cancelField(); onSelect(item.id); }} key={item.id}><i className={activeTimer?.projectId === item.id ? "timing-dot" : ""} />{item.title}</button>)}</aside><section><div className="eyebrow">{project.status === "completed" ? "已完成" : project.status === "paused" ? "暂停中" : "进行中"}</div>{editingField === "title" ? <input autoFocus className="project-title-editor" value={fieldDraft} onChange={(event) => setFieldDraft(event.target.value)} onBlur={saveField} onKeyDown={editorKeyDown} aria-label="项目标题" /> : <h1 className="editable-project-text" onDoubleClick={() => beginEdit("title")}>{project.title}</h1>}<div className="pstat"><span>● <select aria-label="项目状态" value={project.status} onChange={(event) => onUpdate({ ...project, status: event.target.value as Project["status"] })}><option value="active">进行中</option><option value="paused">暂停</option><option value="completed">已完成</option></select></span>{idea && <button className="idea-link" onClick={() => onOpenIdea(idea.id)}>在想法中查看 <ArrowRight size={14} /></button>}<button className="idea-link" onClick={() => onUpdate({ ...project, status: "archived" })}>归档</button></div><section className={`project-timer ${isTiming ? "running" : ""}`}><div><small>本次投入</small><strong>{isTiming ? elapsedLabel : "00:00:00"}</strong><p>{isTiming ? "停止后会自动进入时间记录" : activeTimer ? "另一个项目正在计时" : "开始一次专注，按次留下真实花费"}</p></div>{isTiming ? <button className="timer-stop" onClick={stopTimer}><Square size={16} fill="currentColor" />停止并记录</button> : <button className="timer-start" disabled={Boolean(activeTimer)} onClick={() => onSetTimer({ projectId: project.id, startedAt: new Date().toISOString() })}><Play size={17} fill="currentColor" />开始计时</button>}</section><section className="project-description"><small>项目说明</small>{editingField === "description" ? <textarea autoFocus value={fieldDraft} onChange={(event) => setFieldDraft(event.target.value)} onBlur={saveField} onKeyDown={editorKeyDown} aria-label="项目说明" /> : <p className="editable-project-text" onDoubleClick={() => beginEdit("description")}>{project.description || "还没有补充项目说明。"}</p>}</section><section className="inner-thoughts"><div><small>内心戏</small></div>{editingField === "thoughts" ? <textarea autoFocus aria-label="内心戏" value={fieldDraft} onChange={(event) => setFieldDraft(event.target.value)} onBlur={saveField} onKeyDown={editorKeyDown} placeholder="此刻你真正期待、犹豫或在意的是什么？" /> : <p className="editable-project-text" onDoubleClick={() => beginEdit("thoughts")}>{project.innerThoughts || "这里留给你自己：不必是计划，也可以是一点还没有想明白的话。"}</p>}</section><div className="chat"><header>项目对话 <small>{currentMessages.length} 条 · {llmConfig.model || "未配置模型"}</small></header><div className="messages">{currentMessages.length ? currentMessages.map((message) => <div className={message.role === "user" ? "user" : ""} key={message.id}><b>{message.role === "user" ? "我" : "A"}</b><p>{message.content}</p></div>) : <p className="quiet">说说刚刚发生了什么、卡在哪里，或你想先推进哪一点。</p>}{replying && <div><b>A</b><p>正在想一想…</p></div>}</div><form className="send" onSubmit={(event) => { event.preventDefault(); saveMessage(); }}><input value={messageDraft} onChange={(event) => setMessageDraft(event.target.value)} placeholder="和 Ariadne 说说项目现在的情况…" /><button type="submit" aria-label="发送项目对话" disabled={!messageDraft.trim() || replying}><ArrowUp size={16} /></button></form>{chatError && <div className="llm-error compact"><span>{chatError}</span><button onClick={onOpenModelSettings}>去配置</button></div>}</div></section></div>;
}

function startOfRecordPeriod(value: Date, period: RecordsPeriod) { const start = new Date(value); start.setHours(0, 0, 0, 0); if (period === "week") { const day = start.getDay() || 7; start.setDate(start.getDate() - day + 1); } if (period === "month") start.setDate(1); if (period === "year") { start.setMonth(0, 1); } return start; }
function endOfRecordPeriod(value: Date, period: RecordsPeriod) { const end = startOfRecordPeriod(value, period); if (period === "day") end.setDate(end.getDate() + 1); if (period === "week") end.setDate(end.getDate() + 7); if (period === "month") end.setMonth(end.getMonth() + 1); if (period === "year") end.setFullYear(end.getFullYear() + 1); return end; }
function moveRecordPeriod(value: Date, period: RecordsPeriod, direction: number) { const next = new Date(value); if (period === "day") next.setDate(next.getDate() + direction); if (period === "week") next.setDate(next.getDate() + direction * 7); if (period === "month") next.setMonth(next.getMonth() + direction); if (period === "year") next.setFullYear(next.getFullYear() + direction); return next; }
function formatMinutes(minutes: number) { const seconds = Math.max(1, Math.round(minutes * 60)); if (seconds < 60) return `${seconds} 秒`; const roundedMinutes = Math.round(seconds / 60); return roundedMinutes >= 60 ? `${Math.floor(roundedMinutes / 60)} 小时${roundedMinutes % 60 ? ` ${roundedMinutes % 60} 分` : ""}` : `${roundedMinutes} 分`; }
function dateInputValue(value: Date) { const offset = value.getTimezoneOffset() * 60000; return new Date(value.getTime() - offset).toISOString().slice(0, 10); }
function timeInputValue(value: Date) { return `${String(value.getHours()).padStart(2, "0")}:${String(value.getMinutes()).padStart(2, "0")}`; }

function Records({ records, tags, projects, onAdd }: { records: ActivityRecord[]; tags: Tag[]; projects: Project[]; onAdd: (record: Omit<ActivityRecord, "id">) => void }) {
  const [period, setPeriod] = useState<RecordsPeriod>("day");
  const [anchor, setAnchor] = useState(() => new Date());
  const [formOpen, setFormOpen] = useState(false);
  const [title, setTitle] = useState("");
  const [minutes, setMinutes] = useState("45");
  const [tagId, setTagId] = useState("");
  const [projectId, setProjectId] = useState("");
  const [note, setNote] = useState("");
  const [recordDate, setRecordDate] = useState(() => dateInputValue(new Date()));
  const [recordTime, setRecordTime] = useState(() => timeInputValue(new Date()));
  const start = startOfRecordPeriod(anchor, period);
  const end = endOfRecordPeriod(anchor, period);
  const shown = records.filter((record) => { const date = new Date(record.completedAt); return date >= start && date < end; }).sort((a, b) => +new Date(b.completedAt) - +new Date(a.completedAt));
  const total = shown.reduce((sum, record) => sum + record.minutes, 0);
  const colors = ["#c7663d", "#756199", "#cf9a54", "#5c8276", "#a56d86"];
  const colorFor = (record: ActivityRecord) => colors[Math.abs((record.projectId ?? record.tagId ?? record.title).split("").reduce((sum, char) => sum + char.charCodeAt(0), 0)) % colors.length];
  const rangeLabel = period === "day" ? new Intl.DateTimeFormat("zh-CN", { month: "long", day: "numeric", weekday: "long" }).format(anchor) : period === "week" ? `${new Intl.DateTimeFormat("zh-CN", { month: "numeric", day: "numeric" }).format(start)} — ${new Intl.DateTimeFormat("zh-CN", { month: "numeric", day: "numeric" }).format(new Date(end.getTime() - 1))}` : period === "month" ? new Intl.DateTimeFormat("zh-CN", { year: "numeric", month: "long" }).format(anchor) : `${anchor.getFullYear()} 年`;
  const labels = period === "week" ? ["一", "二", "三", "四", "五", "六", "日"] : period === "month" ? ["第 1 周", "第 2 周", "第 3 周", "第 4 周", "第 5 周"] : ["1月", "2月", "3月", "4月", "5月", "6月", "7月", "8月", "9月", "10月", "11月", "12月"];
  const values = labels.map((_, index) => shown.reduce((sum, record) => { const date = new Date(record.completedAt); if (period === "week") return (date.getDay() || 7) === index + 1 ? sum + record.minutes : sum; if (period === "year") return date.getMonth() === index ? sum + record.minutes : sum; return Math.floor((date.getDate() - 1) / 7) === index ? sum + record.minutes : sum; }, 0));
  const maxValue = Math.max(...values, 1);
  const save = () => { const duration = Number(minutes); if (!title.trim() || !Number.isFinite(duration) || duration <= 0) return; const startedAt = new Date(`${recordDate}T${recordTime}:00`); const completedAt = new Date(startedAt.getTime() + duration * 60000); onAdd({ title: title.trim(), minutes: duration, tagId: tagId || null, projectId: projectId || null, note: note.trim(), startedAt: startedAt.toISOString(), completedAt: completedAt.toISOString() }); setTitle(""); setMinutes("45"); setTagId(""); setProjectId(""); setNote(""); setRecordTime(timeInputValue(new Date())); setFormOpen(false); };
  const timelineHours = Array.from({ length: 19 }, (_, index) => index + 6);
  const timelineRecords = shown.map((record) => { const completed = new Date(record.completedAt); const started = record.startedAt ? new Date(record.startedAt) : new Date(completed.getTime() - record.minutes * 60000); const startMinute = started.getHours() * 60 + started.getMinutes(); const top = Math.max(0, Math.min(100, ((startMinute - 360) / 1080) * 100)); const height = Math.max(2.8, Math.min(100 - top, (record.minutes / 1080) * 100)); return { record, started, completed, top, height }; });
  return <div className="page records-page">
    <header className="records-heading"><div><div className="eyebrow">TIME DIARY</div><h1>今天的时间，落在哪里</h1><p>计时完成后会自动落入一天的时间轴，也可以手动补记。</p></div><button className="primary" onClick={() => setFormOpen((open) => !open)}>{formOpen ? <X size={16} /> : <Plus size={16} />}{formOpen ? "收起" : "补记时间"}</button></header>
    {formOpen && <section className="record-form calendar-form"><label className="record-title-field"><span>做了什么？</span><input autoFocus value={title} onChange={(event) => setTitle(event.target.value)} placeholder="例如：整理项目访谈笔记" /></label><label><span>日期</span><input type="date" value={recordDate} onChange={(event) => setRecordDate(event.target.value)} /></label><label><span>开始</span><input type="time" value={recordTime} onChange={(event) => setRecordTime(event.target.value)} /></label><label><span>时长</span><input type="number" min="1" value={minutes} onChange={(event) => setMinutes(event.target.value)} /><em>分钟</em></label><label><span>关联项目</span><select value={projectId} onChange={(event) => setProjectId(event.target.value)}><option value="">不关联</option>{projects.filter((project) => project.status !== "archived").map((project) => <option key={project.id} value={project.id}>{project.title}</option>)}</select></label><label><span>标签</span><select value={tagId} onChange={(event) => setTagId(event.target.value)}><option value="">不分类</option>{tags.filter((tag) => tag.parentId !== null).map((tag) => <option key={tag.id} value={tag.id}>{tagPath(tag, tags)}</option>)}</select></label><label className="record-note-field"><span>备注</span><input value={note} onChange={(event) => setNote(event.target.value)} placeholder="可选" /></label><button className="primary" onClick={save}>留下记录 <ArrowRight size={16} /></button></section>}
    <div className="record-toolbar"><div className="record-periods" role="tablist" aria-label="记录时间范围">{(["day", "week", "month", "year"] as RecordsPeriod[]).map((item) => <button key={item} className={period === item ? "active" : ""} onClick={() => setPeriod(item)} role="tab" aria-selected={period === item}>{{ day: "日", week: "周", month: "月", year: "年" }[item]}</button>)}</div><div className="record-range"><button aria-label="查看上一段时间" onClick={() => setAnchor((current) => moveRecordPeriod(current, period, -1))}><ChevronLeft size={18} /></button><b>{rangeLabel}</b><button aria-label="查看下一段时间" onClick={() => setAnchor((current) => moveRecordPeriod(current, period, 1))}><ChevronRight size={18} /></button></div></div>
    {shown.length ? <>{period === "day" ? <div className="calendar-layout"><section className="day-timeline"><div className="timeline-summary"><div><small>今天已记录</small><strong>{formatMinutes(total)}</strong></div><span>{shown.length} 段活动</span></div><div className="time-grid"><div className="hour-labels">{timelineHours.map((hour) => <span key={hour}>{String(hour).padStart(2, "0")}:00</span>)}</div><div className="time-track">{timelineHours.map((hour) => <i key={hour} />)}{timelineRecords.map(({ record, started, completed, top, height }) => <article className="time-block" key={record.id} style={{ top: `${top}%`, height: `${height}%`, background: colorFor(record) }}><div><b>{record.title}</b><span>{timeInputValue(started)} – {timeInputValue(completed)}</span></div><strong>{formatMinutes(record.minutes)}</strong></article>)}</div></div></section><aside className="day-log"><div className="eyebrow">DAY LOG</div><h2>今天发生过的事</h2>{shown.map((record) => <article key={record.id}><i style={{ background: colorFor(record) }} /><div><b>{record.title}</b><span>{projects.find((project) => project.id === record.projectId)?.title ?? tags.find((tag) => tag.id === record.tagId)?.name ?? "未分类"}{record.note ? ` · ${record.note}` : ""}</span></div><strong>{formatMinutes(record.minutes)}</strong></article>)}</aside></div> : <><section className="record-summary"><div><small>已经投入</small><strong>{formatMinutes(total)}</strong><p>{shown.length} 次真实发生的活动</p></div><div className="record-summary-note"><Clock3 size={18} /><span>时间会从每一次计时和补记中自动汇总。</span></div></section><section className="record-chart overview-chart"><div className="chart-title"><div><div className="eyebrow">TIME FLOW</div><h2>时间分布</h2></div><small>分钟</small></div><div className="record-bars">{labels.map((label, index) => <div key={label}><span><i style={{ height: `${Math.max((values[index] / maxValue) * 100, values[index] ? 8 : 0)}%` }} /></span><b>{label}</b></div>)}</div></section><section className="record-list"><div className="chart-title"><div><div className="eyebrow">WHAT HAPPENED</div><h2>这段时间做过的事</h2></div><small>{shown.length} 条</small></div>{shown.map((record) => <article key={record.id}><i style={{ background: colorFor(record) }} /><div><h3>{record.title}</h3><p>{projects.find((project) => project.id === record.projectId)?.title ?? tags.find((tag) => tag.id === record.tagId)?.name ?? "未分类"} · {new Intl.DateTimeFormat("zh-CN", { month: "numeric", day: "numeric", weekday: "short" }).format(new Date(record.completedAt))}{record.note ? ` · ${record.note}` : ""}</p></div><b>{formatMinutes(record.minutes)}</b></article>)}</section></>}</> : <section className="records-empty"><Clock3 size={23} /><h2>这一段时间，还没有留下记录。</h2><p>从项目页开始计时，或在这里补记一段。</p></section>}
  </div>;
}

function RecordsLegacy({ records, tags, projects, onAdd }: { records: ActivityRecord[]; tags: Tag[]; projects: Project[]; onAdd: (record: Omit<ActivityRecord, "id">) => void }) {
  const [period, setPeriod] = useState<RecordsPeriod>("day"); const [anchor, setAnchor] = useState(() => new Date()); const [formOpen, setFormOpen] = useState(false); const [title, setTitle] = useState(""); const [minutes, setMinutes] = useState("45"); const [tagId, setTagId] = useState(""); const [projectId, setProjectId] = useState(""); const [note, setNote] = useState(""); const [recordDate, setRecordDate] = useState(() => dateInputValue(new Date())); const [recordTime, setRecordTime] = useState(() => timeInputValue(new Date()));
  const start = startOfRecordPeriod(anchor, period); const end = endOfRecordPeriod(anchor, period);
  const shown = records.filter((record) => { const date = new Date(record.completedAt); return date >= start && date < end; }).sort((a, b) => +new Date(b.completedAt) - +new Date(a.completedAt));
  const total = shown.reduce((sum, record) => sum + record.minutes, 0);
  const categories = shown.reduce<{ label: string; minutes: number; color: string }[]>((items, record) => { const label = tags.find((tag) => tag.id === record.tagId)?.name ?? "未分类"; const existing = items.find((item) => item.label === label); if (existing) existing.minutes += record.minutes; else items.push({ label, minutes: record.minutes, color: ["#c7663d", "#756199", "#cf9a54", "#5c8276", "#a56d86"][items.length % 5] }); return items; }, []).sort((a, b) => b.minutes - a.minutes);
  const barLabels = period === "week" ? ["一", "二", "三", "四", "五", "六", "日"] : period === "year" ? ["1月", "2月", "3月", "4月", "5月", "6月", "7月", "8月", "9月", "10月", "11月", "12月"] : period === "month" ? ["第 1 周", "第 2 周", "第 3 周", "第 4 周", "第 5 周"] : shown.map((record, index) => `${index + 1}`);
  const barValues = period === "day" ? shown.map((record) => record.minutes) : barLabels.map((_, index) => shown.reduce((sum, record) => { const date = new Date(record.completedAt); if (period === "week") return (date.getDay() || 7) === index + 1 ? sum + record.minutes : sum; if (period === "year") return date.getMonth() === index ? sum + record.minutes : sum; return Math.floor((date.getDate() - 1) / 7) === index ? sum + record.minutes : sum; }, 0));
  const maxBar = Math.max(...barValues, 1);
  const rangeLabel = period === "day" ? new Intl.DateTimeFormat("zh-CN", { month: "long", day: "numeric", weekday: "long" }).format(anchor) : period === "week" ? `${new Intl.DateTimeFormat("zh-CN", { month: "numeric", day: "numeric" }).format(start)} — ${new Intl.DateTimeFormat("zh-CN", { month: "numeric", day: "numeric" }).format(new Date(end.getTime() - 1))}` : period === "month" ? new Intl.DateTimeFormat("zh-CN", { year: "numeric", month: "long" }).format(anchor) : `${anchor.getFullYear()} 年`;
  const gradient = categories.length ? `conic-gradient(${categories.map((item, index) => { const previous = categories.slice(0, index).reduce((sum, entry) => sum + entry.minutes, 0); return `${item.color} ${(previous / total) * 100}% ${((previous + item.minutes) / total) * 100}%`; }).join(", ")})` : "";
  const save = () => { const duration = Number(minutes); if (!title.trim() || !Number.isFinite(duration) || duration <= 0) return; const startedAt = new Date(`${recordDate}T${recordTime}:00`); const completedAt = new Date(startedAt.getTime() + duration * 60000); onAdd({ title: title.trim(), minutes: duration, tagId: tagId || null, projectId: projectId || null, note: note.trim(), startedAt: startedAt.toISOString(), completedAt: completedAt.toISOString() }); setTitle(""); setMinutes("45"); setTagId(""); setProjectId(""); setNote(""); setRecordTime(timeInputValue(new Date())); setFormOpen(false); };
  return <div className="page records-page"><header className="records-heading"><div><div className="eyebrow">TIME LEFT BEHIND</div><h1>线在延伸</h1><p>走过的地方，都算数。</p></div><button className="primary" onClick={() => setFormOpen((open) => !open)}>{formOpen ? <X size={16} /> : <Plus size={16} />}{formOpen ? "收起" : "记一段时间"}</button></header>{formOpen && <section className="record-form"><label><span>刚刚做了什么？</span><input autoFocus value={title} onChange={(event) => setTitle(event.target.value)} placeholder="例如：整理项目的访谈笔记" /></label><label><span>花了多久？</span><input type="number" min="1" value={minutes} onChange={(event) => setMinutes(event.target.value)} /><em>分钟</em></label><label><span>归到哪里？</span><select value={tagId} onChange={(event) => setTagId(event.target.value)}><option value="">不分类</option>{tags.filter((tag) => tag.parentId !== null).map((tag) => <option key={tag.id} value={tag.id}>{tagPath(tag, tags)}</option>)}</select></label><label><span>关联项目</span><select value={projectId} onChange={(event) => setProjectId(event.target.value)}><option value="">不关联项目</option>{projects.filter((project) => project.status !== "archived").map((project) => <option key={project.id} value={project.id}>{project.title}</option>)}</select></label><label><span>哪一天？</span><input type="date" value={recordDate} onChange={(event) => setRecordDate(event.target.value)} /></label><label><span>留下什么？</span><input value={note} onChange={(event) => setNote(event.target.value)} placeholder="可选的简短说明" /></label><button className="primary" onClick={save}>留下记录 <ArrowRight size={16} /></button></section>}<div className="record-periods" role="tablist" aria-label="记录时间范围">{(["day", "week", "month", "year"] as RecordsPeriod[]).map((item) => <button key={item} className={period === item ? "active" : ""} onClick={() => setPeriod(item)} role="tab" aria-selected={period === item}>{{ day: "每日", week: "每周", month: "每月", year: "每年" }[item]}</button>)}</div><div className="record-range"><button aria-label="查看上一段时间" onClick={() => setAnchor((current) => moveRecordPeriod(current, period, -1))}><ChevronLeft size={18} /></button><b>{rangeLabel}</b><button aria-label="查看下一段时间" onClick={() => setAnchor((current) => moveRecordPeriod(current, period, 1))}><ChevronRight size={18} /></button></div>{shown.length ? <><section className="record-summary"><div><small>已经投入</small><strong>{formatMinutes(total)}</strong><p>{shown.length} 次真实发生的活动</p></div><div className="record-summary-note"><Clock3 size={18} /><span>最多的一件事是 <b>{categories[0]?.label}</b><br />占用了 {categories[0] ? Math.round((categories[0].minutes / total) * 100) : 0}% 的已记录时间</span></div></section><div className="record-charts"><section className="record-chart"><div className="chart-title"><div><div className="eyebrow">TIME FLOW</div><h2>时间流向</h2></div><small>分钟</small></div><div className="record-bars">{barLabels.map((label, index) => <div key={`${label}-${index}`}><span><i style={{ height: `${Math.max((barValues[index] / maxBar) * 100, barValues[index] ? 8 : 0)}%` }} /></span><b>{label}</b></div>)}</div></section><section className="record-chart record-pie-card"><div className="chart-title"><div><div className="eyebrow">WHAT HELD YOU</div><h2>投入了什么</h2></div></div><div className="pie-layout"><div className="record-pie" style={{ background: gradient }}><span><b>{formatMinutes(total)}</b><small>总计</small></span></div><div className="pie-legend">{categories.map((item) => <div key={item.label}><i style={{ background: item.color }} /><span>{item.label}</span><b>{Math.round((item.minutes / total) * 100)}%</b></div>)}</div></div></section></div><section className="record-list"><div className="chart-title"><div><div className="eyebrow">WHAT HAPPENED</div><h2>这段时间做过的事</h2></div><small>{shown.length} 条</small></div>{shown.map((record) => <article key={record.id}><i style={{ background: categories.find((item) => item.label === (tags.find((tag) => tag.id === record.tagId)?.name ?? "未分类"))?.color }} /><div><h3>{record.title}</h3><p>{projects.find((project) => project.id === record.projectId)?.title ?? tags.find((tag) => tag.id === record.tagId)?.name ?? "未分类"} · {new Intl.DateTimeFormat("zh-CN", { month: "numeric", day: "numeric", weekday: "short" }).format(new Date(record.completedAt))}{record.note ? ` · ${record.note}` : ""}</p></div><b>{formatMinutes(record.minutes)}</b></article>)}</section></> : <section className="records-empty"><Clock3 size={23} /><h2>这一段时间，还没有留下记录。</h2><p>完成一件事之后，再把它留在这里。</p></section>}</div>;
}

function Profile({ ideas, projects, tags, records, llmConfig, onUpdateLlmConfig, onRestoreIdea, onRestoreProject }: { ideas: Idea[]; projects: Project[]; tags: Tag[]; records: ActivityRecord[]; llmConfig: LlmConfig; onUpdateLlmConfig: (config: LlmConfig) => void; onRestoreIdea: (idea: Idea) => void; onRestoreProject: (project: Project) => void }) {
  const [tab, setTab] = useState<ProfileTab>("overview");
  const [draft, setDraft] = useState<LlmConfig>(llmConfig);
  const [showKey, setShowKey] = useState(false);
  const [saved, setSaved] = useState(false);
  useEffect(() => setDraft(llmConfig), [llmConfig]);
  const activeIdeas = ideas.filter((idea) => idea.status !== "archived");
  const activeProjects = projects.filter((project) => project.status !== "archived");
  const archivedIdeas = ideas.filter((idea) => idea.status === "archived").sort((a, b) => +new Date(b.updatedAt) - +new Date(a.updatedAt));
  const archivedProjects = projects.filter((project) => project.status === "archived").sort((a, b) => +new Date(b.updatedAt) - +new Date(a.updatedAt));
  const archivedCount = archivedIdeas.length + archivedProjects.length;
  const totalMinutes = records.reduce((sum, record) => sum + record.minutes, 0);
  const chooseProvider = (provider: LlmConfig["provider"]) => setDraft((current) => ({ ...current, provider, ...providerPresets[provider] }));
  const saveModel = () => { onUpdateLlmConfig({ ...draft, apiKey: draft.apiKey.trim(), baseUrl: draft.baseUrl.trim(), model: draft.model.trim() }); setSaved(true); window.setTimeout(() => setSaved(false), 1800); };
  return <div className="page profile-page"><div className="profilehead"><b>我</b><div><div className="eyebrow">MY SPACE</div><h1>我的线索</h1><p>管理你的内容、模型连接和暂时放下的项目。</p></div></div><div className="profile-tabs"><button className={tab === "overview" ? "active" : ""} onClick={() => setTab("overview")}>概览</button><button className={tab === "model" ? "active" : ""} onClick={() => setTab("model")}><KeyRound size={14} />模型</button><button className={tab === "archive" ? "active" : ""} onClick={() => setTab("archive")}><Archive size={14} />归档 <span>{archivedCount}</span></button></div>
    {tab === "model" ? <section className="model-settings"><div className="model-settings-head"><div><div className="eyebrow">LLM CONNECTION</div><h2>接入你的模型</h2><p>首页的想法引导和项目推进对话会共用这组配置。</p></div><span className={llmConfig.apiKey ? "connected" : ""}>{llmConfig.apiKey ? "已接入" : "未配置"}</span></div><div className="model-form"><label><span>服务商</span><select value={draft.provider} onChange={(event) => chooseProvider(event.target.value as LlmConfig["provider"])}><option value="deepseek">DeepSeek</option><option value="openai">OpenAI</option><option value="qwen">通义千问</option><option value="kimi">Kimi</option><option value="custom">其他 OpenAI 兼容服务</option></select></label><label className="api-key-field"><span>API Key</span><div><input type={showKey ? "text" : "password"} value={draft.apiKey} onChange={(event) => setDraft({ ...draft, apiKey: event.target.value })} placeholder="粘贴你在服务商购买的 API Key" autoComplete="off" /><button type="button" onClick={() => setShowKey((value) => !value)} aria-label={showKey ? "隐藏 API Key" : "显示 API Key"}>{showKey ? <EyeOff size={17} /> : <Eye size={17} />}</button></div></label><label><span>接口地址</span><input value={draft.baseUrl} onChange={(event) => setDraft({ ...draft, baseUrl: event.target.value })} placeholder="https://…/chat/completions" /></label><label><span>模型名称</span><input value={draft.model} onChange={(event) => setDraft({ ...draft, model: event.target.value })} placeholder="服务商提供的模型 ID" /></label></div><div className="model-save-row"><p><KeyRound size={14} />API Key 只保存在当前设备的浏览器中，并会由浏览器直接发送给你选择的服务商。</p><button className="primary" onClick={saveModel}>{saved ? <Check size={16} /> : <KeyRound size={16} />}{saved ? "已保存" : "保存连接"}</button></div></section> : tab === "archive" ? <section className="archive-panel"><div className="section-heading"><div><div className="eyebrow">ARCHIVE</div><h2>暂时放下的内容</h2><p>归档不会删除，需要时可以恢复。</p></div><span>{archivedCount} 项</span></div>{archivedCount ? <div className="archive-list">{archivedIdeas.map((idea) => <article key={idea.id}><div className="archive-kind"><Lightbulb size={15} />想法</div><div><h3>{idea.title}</h3><p>{idea.content || "没有补充说明"}</p><small>归档于 {dateLabel(idea.updatedAt)}</small></div><button onClick={() => onRestoreIdea(idea)}>恢复 <ArrowRight size={15} /></button></article>)}{archivedProjects.map((project) => <article key={project.id}><div className="archive-kind"><BookOpen size={15} />项目</div><div><h3>{project.title}</h3><p>{project.description || "没有补充说明"}</p><small>归档于 {dateLabel(project.updatedAt)}</small></div><button onClick={() => onRestoreProject(project)}>恢复 <ArrowRight size={15} /></button></article>)}</div> : <div className="archive-empty"><Archive size={22} /><h3>归档库还是空的</h3><p>当你想先放下某个想法或项目时，它会安静地留在这里。</p></div>}</section> : <><div className="profile-summary"><section className="focus-card"><div className="eyebrow">NOW</div><h2>此刻，你正留下自己的线。</h2><p>想法、项目和每一次真实投入，都在这里慢慢连起来。</p><div className="stats"><div><b>{activeIdeas.length}</b><small>正在保存的想法</small></div><div><b>{activeProjects.length}</b><small>正在进行的项目</small></div><div><b>{formatMinutes(totalMinutes)}</b><small>累计记录时间</small></div></div></section><section className="model-teaser"><KeyRound size={20} /><div><div className="eyebrow">YOUR MODEL</div><h2>{llmConfig.apiKey ? `${llmConfig.model} 已接入` : "接入你的 AI 模型"}</h2><p>{llmConfig.apiKey ? "首页和项目对话已可以使用。" : "配置一次，两处对话共用。"}</p></div><button onClick={() => setTab("model")}>管理连接 <ArrowRight size={15} /></button></section></div></>}
  </div>;
}

function ProfileLegacy({ ideas, projects, tags, records, onRestoreIdea, onRestoreProject }: { ideas: Idea[]; projects: Project[]; tags: Tag[]; records: ActivityRecord[]; onRestoreIdea: (idea: Idea) => void; onRestoreProject: (project: Project) => void }) {
  const [tab, setTab] = useState<ProfileTab>("overview");
  const activeIdeas = ideas.filter((idea) => idea.status !== "archived");
  const activeProjects = projects.filter((project) => project.status !== "archived");
  const archivedIdeas = ideas.filter((idea) => idea.status === "archived").sort((a, b) => +new Date(b.updatedAt) - +new Date(a.updatedAt));
  const archivedProjects = projects.filter((project) => project.status === "archived").sort((a, b) => +new Date(b.updatedAt) - +new Date(a.updatedAt));
  const archivedCount = archivedIdeas.length + archivedProjects.length;
  const tagCounts = new Map<string, number>();
  activeIdeas.forEach((idea) => idea.tagIds.forEach((id) => tagCounts.set(id, (tagCounts.get(id) ?? 0) + 1)));
  records.forEach((record) => { if (record.tagId) tagCounts.set(record.tagId, (tagCounts.get(record.tagId) ?? 0) + 1); });
  const interests = [...tagCounts.entries()].sort((a, b) => b[1] - a[1]).slice(0, 5).map(([id]) => tags.find((tag) => tag.id === id)).filter(Boolean) as Tag[];
  const recent = [...activeIdeas.map((idea) => ({ type: "想法" as const, title: idea.title, date: idea.updatedAt })), ...activeProjects.map((project) => ({ type: "项目" as const, title: project.title, date: project.updatedAt }))].sort((a, b) => +new Date(b.date) - +new Date(a.date)).slice(0, 4);

  return <div className="page profile-page"><div className="profilehead"><b>我</b><div><div className="eyebrow">MY SPACE</div><h1>我的线索</h1><p>这里收着你正在靠近的方向，也留着暂时放下的东西。</p></div></div><div className="profile-tabs"><button className={tab === "overview" ? "active" : ""} onClick={() => setTab("overview")}>概览</button><button className={tab === "archive" ? "active" : ""} onClick={() => setTab("archive")}><Archive size={14} />归档 <span>{archivedCount}</span></button></div>{tab === "archive" ? <section className="archive-panel"><div className="section-heading"><div><div className="eyebrow">ARCHIVE</div><h2>暂时放下的内容</h2><p>归档不会删除。需要时，把它恢复到原来的旅程里。</p></div><span>{archivedCount} 项</span></div>{archivedCount ? <div className="archive-list">{archivedIdeas.map((idea) => <article key={idea.id}><div className="archive-kind"><Lightbulb size={15} />想法</div><div><h3>{idea.title}</h3><p>{idea.content || "没有补充说明"}</p><small>归档于 {dateLabel(idea.updatedAt)}</small></div><button onClick={() => onRestoreIdea(idea)}>恢复 <ArrowRight size={15} /></button></article>)}{archivedProjects.map((project) => <article key={project.id}><div className="archive-kind"><BookOpen size={15} />项目</div><div><h3>{project.title}</h3><p>{project.description || "没有补充说明"}</p><small>归档于 {dateLabel(project.updatedAt)}</small></div><button onClick={() => onRestoreProject(project)}>恢复 <ArrowRight size={15} /></button></article>)}</div> : <div className="archive-empty"><Archive size={22} /><h3>归档库还是空的</h3><p>当你想先放下某个想法或项目时，它会安静地留在这里。</p></div>}</section> : <><div className="profile-summary"><section className="focus-card"><div className="eyebrow">NOW</div><h2>此刻，你正留下自己的线。</h2><p>不必用连续打卡证明什么；每一个被记下、被推进或被放下的念头，都算数。</p><div className="stats"><div><b>{activeIdeas.length}</b><small>正在保存的想法</small></div><div><b>{activeProjects.length}</b><small>正在进行的项目</small></div><div><b>{archivedCount}</b><small>安静归档的内容</small></div></div></section><section className="archive-teaser"><Archive size={19} /><div><div className="eyebrow">ARCHIVE</div><h2>给已完成和暂停的事，一个去处。</h2><p>{archivedCount ? `你有 ${archivedCount} 项内容在归档库中。` : "还没有归档内容。"}</p></div><button onClick={() => setTab("archive")}>打开归档 <ArrowRight size={15} /></button></section></div><div className="profilegrid"><section className="interest-card"><div className="eyebrow">INTEREST TRAIL</div><h2>兴趣轨迹</h2><p>来自你真实保存过的标签，不为你下定义。</p><div className="cloud">{interests.length ? interests.map((tag, index) => <span key={tag.id} className={`interest-${index}`}>{tag.name}</span>) : <small>从为想法添加标签开始，这里会慢慢长出你的方向。</small>}</div></section><section className="recent-card"><div className="eyebrow">RECENTLY LEFT</div><h2>最近留下</h2>{recent.length ? <div className="recent-list">{recent.map((item) => <div key={`${item.type}-${item.title}-${item.date}`}><span>{item.type}</span><p>{item.title}</p><small>{dateLabel(item.date)}</small></div>)}</div> : <p className="quiet-profile">还没有内容。去探索页接住一个刚冒出来的念头吧。</p>}</section><section className="data-card"><div><div className="eyebrow">YOUR DATA</div><h2>你的内容，留在这里</h2><p>想法、项目与归档会保存在当前设备中。归档是整理，不是删除。</p></div><Archive size={24} /></section></div></>}</div>;
}
function Placeholder({ title, description }: { title: string; description: string }) { return <div className="page placeholder-page"><div className="eyebrow">本轮范围之外</div><h1>{title}</h1><p>{description}</p></div>; }
